706	    fn segments_extend_the_ring() {
707	        // With the consumer idle the producer fills every segment,
708	        // switching as each is about to be full, and only then
709	        // reports Full.
710	        for (cap, count) in [(1u32, 2u32), (4, 3), (16, 4)] {
