895	    /// A region's one raw pointer and length, for a pool
896	    /// initialized and then attached over it.
897	    ///
898	    /// - Stacked Borrows: the handle `init` returns holds pointers
899	    ///   under the `&mut` it took, and a write through an attached
900	    ///   handle, which holds the region's own pointer, invalidates
901	    ///   them, so a test drops the initializing handle before it
902	    ///   attaches and never writes through both, the hazard the
903	    ///   pools' `attach` notes.
904	    fn region(r: &mut Region) -> (*mut u8, usize) {
905	        (r.0.as_mut_ptr(), r.0.len())
906	    }
