908	    /// Initialize the test pool over `base` and run `f` on it,
909	    /// dropping the handle after.
910	    fn with_init_pool<R>(base: *mut u8, len: usize, f: impl FnOnce(&mut Pool<'_>) -> R) -> R {
911	        // SAFETY: base and len are the region, and the slice is
912	        // the only use of the region while it lives.
913	        let mut pool = Pool::init(
914	            unsafe { &mut *core::ptr::slice_from_raw_parts_mut(base, len) },
915	            BUF as u32,
916	            BUFS as u32,
917	        )
918	        .unwrap();
919	        f(&mut pool)
920	    }
