36	/// The consuming endpoint: `reserve_slot_with` the oldest
37	/// committed slot, read in place, `release`.
38	pub struct Consumer<'a> {
39	    /// Private state, borrowed by each guard.
40	    pub(super) st: ConsumerState,
41	    _region: PhantomData<&'a [u8]>,
